      "traffic_side": "right"
    },
    {
      "code": "IT",
      "languages": ["Italiano (イタリア語)", "Deutsch (ドイツ語) – Südtirol（南チロル）で併記", "Français (フランス語) – Valle d'Aosta（アオスタ州）で併記"],
